-- LOT 07 - Conteneurs ID 67, 68, 69, 70, 71, 73 et 74
-- ID 69 et 70 ont des references incoherentes avec leur description source; conserver le contenu mais verifier le titre.
-- Intermediaire: ne pas importer seul; sera assemble dans le SQL final.

START TRANSACTION;

UPDATE `conteneurs`
SET `description` = 'Cabina ufficio di 3,00 x 2,40 m, altezza 2,80 m.\n\nSTRUTTURA E ISOLAMENTO\n- Pareti e tetto con pannelli sandwich isolati da 10 cm\n- Profili a taglio termico per ridurre la dispersione energetica\n- Struttura autoportante e stabile in acciaio saldato\n\nFINESTRE E DOTAZIONI\n- Due finestre a battente/basculanti con doppi vetri\n- Porta esterna in acciaio Hörmann\n- Impianto elettrico conforme alle direttive CE, prese da 230 V e lampada LED da soffitto\n- Pavimento isolato in OSB con rivestimento in PVC robusto e facile da pulire\n\nPossiamo realizzare altre dimensioni e colori secondo le specifiche del cliente. Il prezzo indicato comprende l’IVA. Per lo scarico è necessario predisporre attrezzatura adeguata, ad esempio un carrello elevatore o una pala gommata con forche. Condizioni e costi di consegna sono confermati nel preventivo.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Office cabin measuring 3.00 x 2.40 m and 2.80 m high.\n\nSTRUCTURE AND INSULATION\n- Walls and roof with 10 cm insulated sandwich panels\n- Thermally broken profiles to reduce energy loss\n- Self-supporting, stable welded steel structure\n\nWINDOWS AND EQUIPMENT\n- Two double-glazed tilt-and-turn windows\n- Hörmann external steel door\n- CE-compliant electrical installation, 230 V sockets and LED ceiling light\n- Insulated OSB floor with durable, easy-to-clean PVC covering\n\nOther sizes and colours can be made to customer specifications. The stated price includes VAT. Suitable equipment must be provided for unloading, such as a forklift or wheeled loader with forks. Delivery terms and costs are confirmed in the quotation.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de bureau de 3,00 x 2,40 m et de 2,80 m de hauteur.\n\nSTRUCTURE ET ISOLATION\n- Murs et toit en panneaux sandwich isolés de 10 cm\n- Profils à rupture de pont thermique pour limiter les pertes d’énergie\n- Structure autoportante et stable en acier soudé\n\nFENÊTRES ET ÉQUIPEMENTS\n- Deux fenêtres oscillo-battantes à double vitrage\n- Porte extérieure en acier Hörmann\n- Installation électrique conforme CE, prises 230 V et plafonnier LED\n- Plancher isolé en OSB avec revêtement PVC résistant et facile à nettoyer\n\nD’autres dimensions et couleurs peuvent être réalisées selon les spécifications du client. Le prix indiqué inclut la TVA. Un équipement adapté doit être prévu pour le déchargement, par exemple un chariot élévateur ou une chargeuse sur pneus équipée de fourches. Les modalités et coûts de livraison sont confirmés dans le devis.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina de oficina de 3,00 x 2,40 m y 2,80 m de altura.\n\nESTRUCTURA Y AISLAMIENTO\n- Paredes y techo con paneles sándwich aislados de 10 cm\n- Perfiles con rotura de puente térmico para reducir la pérdida de energía\n- Estructura autoportante y estable de acero soldado\n\nVENTANAS Y EQUIPAMIENTO\n- Dos ventanas oscilobatientes con doble acristalamiento\n- Puerta exterior de acero Hörmann\n- Instalación eléctrica conforme a CE, enchufes de 230 V y lámpara LED de techo\n- Suelo aislado de OSB con revestimiento de PVC resistente y fácil de limpiar\n\nSe pueden fabricar otras dimensiones y colores según las especificaciones del cliente. El precio indicado incluye IVA. Para la descarga debe disponerse de equipo adecuado, como una carretilla elevadora o una pala cargadora con horquillas. Las condiciones y los costes de entrega se confirman en el presupuesto.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Bürokabine mit den Massen 3,00 x 2,40 m und einer Höhe von 2,80 m.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 10 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Selbsttragende, stabile Stahlkonstruktion aus geschweisstem Stahl\n\nFENSTER UND AUSSTATTUNG\n- Zwei Drehkippfenster mit Doppelverglasung\n- Äussere Stahltür von Hörmann\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und LED-Deckenleuchte\n- Isolierter OSB-Boden mit strapazierfähiger, pflegeleichter PVC-Oberfläche\n\nAndere Masse und Farben sind nach Kundenspezifikation möglich. Der angegebene Preis enthält die Mehrwertsteuer. Für das Entladen ist geeignete Ausrüstung bereitzustellen, zum Beispiel ein Gabelstapler oder ein Radlader mit Gabeln. Lieferbedingungen und -kosten werden im Angebot bestätigt.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Kantoorunit van 3,00 x 2,40 m en 2,80 m hoog.\n\nCONSTRUCTIE EN ISOLATIE\n- Wanden en dak met geïsoleerde sandwichpanelen van 10 cm\n- Thermisch onderbroken profielen om energieverlies te beperken\n- Zelfdragende, stabiele gelaste staalconstructie\n\nRAMEN EN UITRUSTING\n- Twee draai-kiepramen met dubbele beglazing\n- Externe stalen Hörmann-deur\n- CE-conforme elektrische installatie, 230V-stopcontacten en led-plafondlamp\n- Geïsoleerde OSB-vloer met sterke, gemakkelijk te reinigen PVC-bedekking\n\nAndere afmetingen en kleuren zijn mogelijk volgens de specificaties van de klant. De vermelde prijs is inclusief btw. Voor het lossen moet geschikte apparatuur beschikbaar zijn, zoals een heftruck of wiellader met vorken. De leveringsvoorwaarden en -kosten worden in de offerte bevestigd.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Toimistomoduuli, mitat 3,00 x 2,40 m, korkeus 2,80 m.\n\nRAKENNE JA ERISTYS\n- Seinät ja katto 10 cm:n eristetyistä sandwich-paneeleista\n- Lämpökatkaistut profiilit vähentävät energiahäviötä\n- Itsekantava ja vakaa hitsattu teräsrunko\n\nIKKUNAT JA VARUSTEET\n- Kaksi kaksilasista avattavaa ja kallistettavaa ikkunaa\n- Hörmannin ulkoinen teräsovi\n- CE-vaatimusten mukainen sähköasennus, 230 V:n pistorasiat ja LED-kattovalaisin\n- Eristetty OSB-lattia kestävällä ja helposti puhdistettavalla PVC-pinnalla\n\nMuita mittoja ja värejä voidaan valmistaa asiakkaan vaatimusten mukaan. Ilmoitettu hinta sisältää arvonlisäveron. Purkamiseen on järjestettävä sopiva kalusto, kuten trukki tai haarukoilla varustettu pyöräkuormaaja. Toimitusehdot ja -kulut vahvistetaan tarjouksessa.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Bürokabine mit den Massen 3,00 x 2,40 m und einer Höhe von 2,80 m.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 10 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Selbsttragende, stabile Stahlkonstruktion aus geschweisstem Stahl\n\nFENSTER UND AUSSTATTUNG\n- Zwei Drehkippfenster mit Doppelverglasung\n- Äussere Stahltür von Hörmann\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und LED-Deckenleuchte\n- Isolierter OSB-Boden mit strapazierfähiger, pflegeleichter PVC-Oberfläche\n\nAndere Masse und Farben sind nach Kundenspezifikation möglich. Der angegebene Preis enthält die Mehrwertsteuer. Für das Entladen ist geeignete Ausrüstung bereitzustellen, zum Beispiel ein Gabelstapler oder ein Radlader mit Gabeln. Lieferbedingungen und -kosten werden im Angebot bestätigt.')
WHERE `id` = 67 AND `reference` = 'CABINA PER UFFICIO RESIDENZIALE- Standard Premium';

UPDATE `conteneurs`
SET `description` = 'Cabina ufficio, soggiorno, magazzino o abitazione, dimensioni 4,00 x 2,20 m e altezza 2,70 m.\n\nSTRUTTURA E ISOLAMENTO\n- Pareti e tetto con pannelli sandwich isolati da 7,5 cm\n- Profili a taglio termico per ridurre la dispersione energetica\n- Struttura autoportante e stabile in acciaio saldato\n\nFINESTRE E DOTAZIONI\n- Due finestre a battente/basculanti con doppi vetri\n- Porta esterna in acciaio Hörmann\n- Impianto elettrico conforme alle direttive CE, prese da 230 V e lampada da soffitto\n- Pavimento isolato in OSB con finitura laminata robusta e facile da pulire\n- Radiatore elettrico a parete\n- Occhielli per il sollevamento con gru e guida inferiore per carrello elevatore\n\nPossiamo realizzare altre dimensioni e colori secondo le specifiche del cliente. Per lo scarico, l’acquirente deve predisporre attrezzatura adeguata. Modalità e costi di consegna sono definiti nel preventivo.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Office cabin, living space, storage unit or accommodation, measuring 4.00 x 2.20 m and 2.70 m high.\n\nSTRUCTURE AND INSULATION\n- Walls and roof with 7.5 cm insulated sandwich panels\n- Thermally broken profiles to reduce energy loss\n- Self-supporting, stable welded steel structure\n\nWINDOWS AND EQUIPMENT\n- Two double-glazed tilt-and-turn windows\n- Hörmann external steel door\n- CE-compliant electrical installation, 230 V sockets and ceiling light\n- Insulated OSB floor with a durable, easy-to-clean laminate finish\n- Wall-mounted electric heater\n- Crane lifting eyes and lower forklift guide\n\nOther sizes and colours can be made to customer specifications. The buyer must provide suitable unloading equipment. Delivery terms and costs are set out in the quotation.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de bureau, espace de vie, espace de stockage ou logement, dimensions 4,00 x 2,20 m et hauteur de 2,70 m.\n\nSTRUCTURE ET ISOLATION\n- Murs et toit en panneaux sandwich isolés de 7,5 cm\n- Profils à rupture de pont thermique pour limiter les pertes d’énergie\n- Structure autoportante et stable en acier soudé\n\nFENÊTRES ET ÉQUIPEMENTS\n- Deux fenêtres oscillo-battantes à double vitrage\n- Porte extérieure en acier Hörmann\n- Installation électrique conforme CE, prises 230 V et plafonnier\n- Plancher isolé en OSB avec finition stratifiée résistante et facile à nettoyer\n- Radiateur électrique mural\n- Anneaux de levage pour grue et guide inférieur pour chariot élévateur\n\nD’autres dimensions et couleurs peuvent être réalisées selon les spécifications du client. Le déchargement doit être effectué avec un équipement adapté fourni par l’acheteur. Les modalités et coûts de livraison sont définis dans le devis.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina de oficina, espacio habitable, almacén o alojamiento, de 4,00 x 2,20 m y 2,70 m de altura.\n\nESTRUCTURA Y AISLAMIENTO\n- Paredes y techo con paneles sándwich aislados de 7,5 cm\n- Perfiles con rotura de puente térmico para reducir la pérdida de energía\n- Estructura autoportante y estable de acero soldado\n\nVENTANAS Y EQUIPAMIENTO\n- Dos ventanas oscilobatientes con doble acristalamiento\n- Puerta exterior de acero Hörmann\n- Instalación eléctrica conforme a CE, enchufes de 230 V y lámpara de techo\n- Suelo aislado de OSB con acabado laminado resistente y fácil de limpiar\n- Radiador eléctrico mural\n- Argollas para grúa y guía inferior para carretilla elevadora\n\nSe pueden fabricar otras dimensiones y colores según las especificaciones del cliente. El comprador debe proporcionar el equipo adecuado para la descarga. Las condiciones y los costes de entrega se indican en el presupuesto.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Bürokabine, Wohnraum, Lagerraum oder Unterkunft mit den Massen 4,00 x 2,20 m und einer Höhe von 2,70 m.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 7,5 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Selbsttragende, stabile Stahlkonstruktion aus geschweisstem Stahl\n\nFENSTER UND AUSSTATTUNG\n- Zwei Drehkippfenster mit Doppelverglasung\n- Äussere Stahltür von Hörmann\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und Deckenleuchte\n- Isolierter OSB-Boden mit robuster, pflegeleichter Laminatoberfläche\n- Elektrischer Wandheizkörper\n- Kranösen und untere Staplerführung\n\nAndere Masse und Farben sind nach Kundenspezifikation möglich. Der Käufer muss geeignete Entladeausrüstung bereitstellen. Lieferbedingungen und -kosten werden im Angebot festgelegt.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Kantoorunit, woonruimte, opslagruimte of accommodatie, 4,00 x 2,20 m en 2,70 m hoog.\n\nCONSTRUCTIE EN ISOLATIE\n- Wanden en dak met geïsoleerde sandwichpanelen van 7,5 cm\n- Thermisch onderbroken profielen om energieverlies te beperken\n- Zelfdragende, stabiele gelaste staalconstructie\n\nRAMEN EN UITRUSTING\n- Twee draai-kiepramen met dubbele beglazing\n- Externe stalen Hörmann-deur\n- CE-conforme elektrische installatie, 230V-stopcontacten en plafondlamp\n- Geïsoleerde OSB-vloer met sterke, gemakkelijk te reinigen laminaatafwerking\n- Elektrische wandradiator\n- Hijsogen voor een kraan en onderste heftruckgeleider\n\nAndere afmetingen en kleuren zijn mogelijk volgens de specificaties van de klant. De koper moet geschikte losapparatuur voorzien. De leveringsvoorwaarden en -kosten staan in de offerte.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Toimisto-, oleskelu-, varasto- tai majoitustila, mitat 4,00 x 2,20 m, korkeus 2,70 m.\n\nRAKENNE JA ERISTYS\n- Seinät ja katto 7,5 cm:n eristetyistä sandwich-paneeleista\n- Lämpökatkaistut profiilit vähentävät energiahäviötä\n- Itsekantava ja vakaa hitsattu teräsrunko\n\nIKKUNAT JA VARUSTEET\n- Kaksi kaksilasista avattavaa ja kallistettavaa ikkunaa\n- Hörmannin ulkoinen teräsovi\n- CE-vaatimusten mukainen sähköasennus, 230 V:n pistorasiat ja kattovalaisin\n- Eristetty OSB-lattia kestävällä ja helposti puhdistettavalla laminaattipinnalla\n- Sähköinen seinälämmitin\n- Nostokorvakkeet nosturille ja alaosan trukkiohjain\n\nMuita mittoja ja värejä voidaan valmistaa asiakkaan vaatimusten mukaan. Ostajan on järjestettävä sopiva purkukalusto. Toimitusehdot ja -kulut määritellään tarjouksessa.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Bürokabine, Wohnraum, Lagerraum oder Unterkunft mit den Massen 4,00 x 2,20 m und einer Höhe von 2,70 m.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach mit 7,5 cm starken isolierten Sandwichpaneelen\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Selbsttragende, stabile Stahlkonstruktion aus geschweisstem Stahl\n\nFENSTER UND AUSSTATTUNG\n- Zwei Drehkippfenster mit Doppelverglasung\n- Äussere Stahltür von Hörmann\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und Deckenleuchte\n- Isolierter OSB-Boden mit robuster, pflegeleichter Laminatoberfläche\n- Elektrischer Wandheizkörper\n- Kranösen und untere Staplerführung\n\nAndere Masse und Farben sind nach Kundenspezifikation möglich. Der Käufer muss geeignete Entladeausrüstung bereitstellen. Lieferbedingungen und -kosten werden im Angebot festgelegt.')
WHERE `id` = 68 AND `reference` = 'CABINA UFFICIO, SALOTTO, MAGAZZINO, CASA';

UPDATE `conteneurs`
SET `description` = 'Contenitore snack moderno e funzionale, dimensioni 3,00 x 4,00 m, progettato per la ristorazione veloce e la vendita da asporto. La grande finestra scorrevole permette il servizio diretto alla clientela.\n\nDOTAZIONI DI SERIE\n- Struttura aperta con installazioni a vista e finitura argento/antracite\n- Isolamento in schiuma PU: pareti e pavimento 100 mm, tetto 120 mm\n- Porta d’ingresso secondaria in acciaio, 800 x 2.100 mm\n- Finestra scorrevole per il servizio, 1.600 x 1.200 mm\n- Finestra termica oscillante in PVC, 1.000 x 1.200 mm\n- Impianto elettrico: 18 prese, due prese trifase da 400 V, due apparecchi LED interni, tre interruttori, una lampada LED esterna e quadro elettrico con interruttore differenziale\n- Pavimento rinforzato per uso intensivo, pannelli in legno e rivestimento professionale in PVC\n\nACCESSORI OPZIONALI\nAria condizionata, riscaldamento, rivestimento esterno in pannelli HPL, legno, effetto legno o acciaio, tapparelle, pareti divisorie, WC e lavabo con rubinetteria, scaldabagno, tendalino, veranda coperta in legno, connessione di rete, collegamento per antenna satellitare e illuminazione esterna supplementare.\n\nSono disponibili dimensioni diverse; ogni progetto viene pianificato individualmente. Per preparare un’offerta personalizzata è sufficiente fornire uno schizzo con dimensioni e attrezzature richieste. La fornitura è completa; lo scarico è a carico del cliente. Attrezzatura necessaria: gru, carrello elevatore o pala gommata con forche. Le condizioni e i costi di consegna sono confermati nel preventivo.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Modern, functional snack bar container measuring 3.00 x 4.00 m, designed for quick-service catering and takeaway sales. The large sliding window enables direct service to customers.\n\nSTANDARD EQUIPMENT\n- Open structure with exposed installations and silver/anthracite finish\n- PU foam insulation: 100 mm in walls and floor, 120 mm in roof\n- Secondary steel entrance door, 800 x 2,100 mm\n- Sliding service window, 1,600 x 1,200 mm\n- Thermal PVC tilt window, 1,000 x 1,200 mm\n- Electrical package: 18 sockets, two 400 V three-phase sockets, two indoor LED fittings, three switches, one exterior LED light and electrical panel with residual-current device\n- Heavy-duty floor for intensive use, with wood panels and professional PVC covering\n\nOPTIONAL ACCESSORIES\nAir conditioning, heating, exterior cladding in HPL panels, real wood, wood effect or steel panels, roller shutters, internal partitions, WC and washbasin with taps, water heater, awning, covered wooden veranda, network connection, satellite antenna connection and additional exterior lighting.\n\nOther sizes are available and each project is planned individually. A simple sketch showing the desired dimensions and equipment is sufficient to request a detailed quotation. The unit is supplied complete; unloading is the customer’s responsibility. Unloading equipment required: crane, forklift or wheeled loader with forks. Delivery terms and costs are confirmed in the quotation.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Conteneur snack moderne et fonctionnel de 3,00 x 4,00 m, conçu pour la restauration rapide et la vente à emporter. La grande fenêtre coulissante permet le service direct à la clientèle.\n\nÉQUIPEMENTS DE SÉRIE\n- Structure ouverte avec installations apparentes et finition argentée/anthracite\n- Isolation en mousse PU : 100 mm dans les murs et le sol, 120 mm dans le toit\n- Porte secondaire d’entrée en acier, 800 x 2 100 mm\n- Fenêtre coulissante de service, 1 600 x 1 200 mm\n- Fenêtre oscillo-battante thermique en PVC, 1 000 x 1 200 mm\n- Installation électrique : 18 prises, deux prises triphasées de 400 V, deux luminaires LED intérieurs, trois interrupteurs, une lampe LED extérieure et tableau électrique avec interrupteur différentiel\n- Sol renforcé pour usage intensif, panneaux en bois et revêtement professionnel en PVC\n\nOPTIONS\nClimatisation, chauffage, habillage extérieur en panneaux HPL, bois, imitation bois ou acier, volets roulants, cloisons intérieures, WC et lavabo avec robinetterie, chauffe-eau, store, véranda couverte en bois, connexion réseau, raccordement d’antenne satellite et éclairage extérieur supplémentaire.\n\nD’autres dimensions sont disponibles et chaque projet est étudié individuellement. Un simple croquis indiquant les dimensions et équipements souhaités suffit pour demander une offre détaillée. Le module est fourni complet ; le déchargement est à la charge du client. Équipement requis : grue, chariot élévateur ou chargeuse sur pneus avec fourches. Les modalités et frais de livraison sont confirmés dans le devis.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Contenedor snack moderno y funcional de 3,00 x 4,00 m, diseñado para restauración rápida y venta para llevar. La gran ventana corredera permite atender directamente a los clientes.\n\nEQUIPAMIENTO DE SERIE\n- Estructura abierta con instalaciones a la vista y acabado plateado/antracita\n- Aislamiento de espuma PU: 100 mm en paredes y suelo, 120 mm en el techo\n- Puerta secundaria de acero, 800 x 2.100 mm\n- Ventana corredera de servicio, 1.600 x 1.200 mm\n- Ventana térmica oscilante de PVC, 1.000 x 1.200 mm\n- Instalación eléctrica: 18 enchufes, dos tomas trifásicas de 400 V, dos luminarias LED interiores, tres interruptores, una lámpara LED exterior y cuadro eléctrico con interruptor diferencial\n- Suelo reforzado para uso intensivo, con paneles de madera y revestimiento profesional de PVC\n\nACCESORIOS OPCIONALES\nAire acondicionado, calefacción, revestimiento exterior de paneles HPL, madera, imitación madera o acero, persianas, tabiques interiores, WC y lavabo con grifería, calentador de agua, toldo, veranda cubierta de madera, conexión de red, conexión de antena parabólica e iluminación exterior adicional.\n\nHay otras dimensiones disponibles y cada proyecto se planifica individualmente. Para solicitar un presupuesto detallado basta con facilitar un croquis con las dimensiones y el equipamiento deseados. El módulo se suministra completo; la descarga corre a cargo del cliente. Equipo necesario: grúa, carretilla elevadora o pala cargadora con horquillas. Las condiciones y los costes de entrega se confirman en el presupuesto.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Moderner, funktionaler Snackcontainer mit den Massen 3,00 x 4,00 m, ausgelegt für Schnellgastronomie und Take-away-Verkauf. Das grosse Schiebefenster ermöglicht den direkten Kundenservice.\n\nSERIENAUSSTATTUNG\n- Offene Struktur mit sichtbaren Installationen und silberner/anthrazitfarbener Ausführung\n- PU-Schaumisolierung: 100 mm in Wänden und Boden, 120 mm im Dach\n- Seitliche Eingangstür aus Stahl, 800 x 2.100 mm\n- Schiebefenster für den Verkauf, 1.600 x 1.200 mm\n- Thermisches PVC-Kippfenster, 1.000 x 1.200 mm\n- Elektroausstattung: 18 Steckdosen, zwei 400-V-Drehstromsteckdosen, zwei LED-Innenleuchten, drei Schalter, eine LED-Aussenleuchte und Elektrokasten mit Fehlerstromschutzschalter\n- Verstärkter Boden für intensive Nutzung, Holzplatten mit professionellem PVC-Belag\n\nOPTIONALES ZUBEHÖR\nKlimaanlage, Heizung, Aussenverkleidung aus HPL-Platten, Holz, Holzoptik oder Stahlplatten, Rollläden, Innenwände, WC und Waschbecken mit Armaturen, Warmwasserbereiter, Markise, überdachte Holzveranda, Netzwerkanschluss, Satellitenantennenanschluss und zusätzliche Aussenbeleuchtung.\n\nWeitere Masse sind verfügbar; jedes Projekt wird individuell geplant. Für eine detaillierte Offerte genügt eine einfache Skizze mit den gewünschten Massen und der Ausstattung. Die Einheit wird vollständig geliefert; das Entladen ist Sache des Kunden. Benötigte Ausrüstung: Kran, Gabelstapler oder Radlader mit Gabeln. Lieferbedingungen und -kosten werden im Angebot bestätigt.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Moderne, functionele snackcontainer van 3,00 x 4,00 m, ontworpen voor snelle horeca en afhaalverkoop. Het grote schuifraam maakt directe bediening van klanten mogelijk.\n\nSTANDAARDUITRUSTING\n- Open constructie met zichtbare installaties en zilver/antraciet afwerking\n- PU-schuimisolatie: 100 mm in wanden en vloer, 120 mm in het dak\n- Secundaire stalen toegangsdeur, 800 x 2.100 mm\n- Schuifraam voor de verkoop, 1.600 x 1.200 mm\n- Thermisch PVC-kiepraam, 1.000 x 1.200 mm\n- Elektrisch pakket: 18 stopcontacten, twee 400V-driefasenaansluitingen, twee led-armaturen binnen, drie schakelaars, één ledlamp buiten en elektriciteitskast met aardlekschakelaar\n- Versterkte vloer voor intensief gebruik, houten panelen met professionele PVC-bedekking\n\nOPTIONELE ACCESSOIRES\nAirconditioning, verwarming, gevelbekleding van HPL-panelen, hout, houtlook of staal, rolluiken, binnenwanden, WC en wastafel met kranen, boiler, luifel, overdekte houten veranda, netwerkaansluiting, aansluiting voor satellietantenne en extra buitenverlichting.\n\nAndere afmetingen zijn beschikbaar en elk project wordt individueel gepland. Een eenvoudige schets met de gewenste afmetingen en uitrusting volstaat voor een gedetailleerde offerte. De unit wordt compleet geleverd; lossen is voor rekening van de klant. Benodigde apparatuur: kraan, heftruck of wiellader met vorken. De leveringsvoorwaarden en -kosten worden in de offerte bevestigd.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Moderni ja toimiva 3,00 x 4,00 m:n snack-kontti, suunniteltu pikaruokailuun ja mukaan myyntiin. Suuri liukuikkuna mahdollistaa suoran asiakaspalvelun.\n\nVAKIOVARUSTEET\n- Avoin rakenne, näkyvät asennukset ja hopean/antrasiitin väritys\n- PU-vaahtoeristys: seinissä ja lattiassa 100 mm, katossa 120 mm\n- Toissijainen teräsovi, 800 x 2 100 mm\n- Myyntikäyttöön tarkoitettu liukuikkuna, 1 600 x 1 200 mm\n- Lämpöä eristävä PVC-kippi-ikkuna, 1 000 x 1 200 mm\n- Sähköpaketti: 18 pistorasiaa, kaksi 400 V:n kolmivaihepistorasiaa, kaksi sisätilojen LED-valaisinta, kolme katkaisinta, yksi ulkoinen LED-valaisin ja sähkökeskus vikavirtasuojalla\n- Vahvistettu lattia kovaan käyttöön, puupaneelit ja ammattitason PVC-pinnoite\n\nLISÄVARUSTEET\nIlmastointi, lämmitys, ulkoverhous HPL-paneeleilla, puulla, puujäljitelmällä tai teräspaneeleilla, rullaverhot, väliseinät, WC ja pesuallas hanoineen, vedenlämmitin, markiisi, katettu puuveranta, verkkoyhteys, satelliittiantenniliitäntä ja lisäulkovalaistus.\n\nMuita kokoja on saatavilla ja jokainen projekti suunnitellaan erikseen. Yksityiskohtaista tarjousta varten riittää luonnos, jossa näkyvät halutut mitat ja varusteet. Moduuli toimitetaan kokonaisena; purku on asiakkaan vastuulla. Purkuun tarvitaan nosturi, trukki tai haarukoilla varustettu pyöräkuormaaja. Toimitusehdot ja -kulut vahvistetaan tarjouksessa.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Moderner, funktionaler Snackcontainer mit den Massen 3,00 x 4,00 m, ausgelegt für Schnellgastronomie und Take-away-Verkauf. Das grosse Schiebefenster ermöglicht den direkten Kundenservice.\n\nSERIENAUSSTATTUNG\n- Offene Struktur mit sichtbaren Installationen und silberner/anthrazitfarbener Ausführung\n- PU-Schaumisolierung: 100 mm in Wänden und Boden, 120 mm im Dach\n- Seitliche Eingangstür aus Stahl, 800 x 2.100 mm\n- Schiebefenster für den Verkauf, 1.600 x 1.200 mm\n- Thermisches PVC-Kippfenster, 1.000 x 1.200 mm\n- Elektroausstattung: 18 Steckdosen, zwei 400-V-Drehstromsteckdosen, zwei LED-Innenleuchten, drei Schalter, eine LED-Aussenleuchte und Elektrokasten mit Fehlerstromschutzschalter\n- Verstärkter Boden für intensive Nutzung, Holzplatten mit professionellem PVC-Belag\n\nOPTIONALES ZUBEHÖR\nKlimaanlage, Heizung, Aussenverkleidung aus HPL-Platten, Holz, Holzoptik oder Stahlplatten, Rollläden, Innenwände, WC und Waschbecken mit Armaturen, Warmwasserbereiter, Markise, überdachte Holzveranda, Netzwerkanschluss, Satellitenantennenanschluss und zusätzliche Aussenbeleuchtung.\n\nWeitere Masse sind verfügbar; jedes Projekt wird individuell geplant. Für eine detaillierte Offerte genügt eine einfache Skizze mit den gewünschten Massen und der Ausstattung. Die Einheit wird vollständig geliefert; das Entladen ist Sache des Kunden. Benötigte Ausrüstung: Kran, Gabelstapler oder Radlader mit Gabeln. Lieferbedingungen und -kosten werden im Angebot bestätigt.')
WHERE `id` = 69 AND `reference` = 'CABINA DA UFFICIO CON AMPIA FINESTRA SCORREVOLE';

UPDATE `conteneurs`
SET `description` = 'Sauna esterna di alta gamma, dimensioni 4,00 x 2,20 m. Fornita completamente montata e pronta all’uso per impiego privato o professionale, ad esempio in hotel, spa e centri benessere.\n\nDOTAZIONI DI SERIE\n- Stufa HARVIA VEGA da 9 kW, alimentazione 400 V, pietre incluse e unità di controllo integrata\n- Rivestimento interno e griglia per le pietre in acciaio inossidabile\n- Controllo digitale con orologio 24 ore, regolazione della temperatura da 30 a 115 °C, limitazione del tempo di riscaldamento e visualizzazione digitale\n- Blocco dei tasti, sonda di temperatura e limitatore di sicurezza a 139 °C\n- Due panche robuste con tavolo integrato, in abete rosso nordico\n\nCOSTRUZIONE E ISOLAMENTO\n- Pareti e tetto in pannelli sandwich con isolamento da 7,5 cm\n- Struttura autoportante in acciaio saldato\n- Due finestre a battente con doppi vetri\n- Impianto elettrico completo, plafoniere interne e radiatore elettrico a parete da 2.000 W\n\nConsegna e scarico sono concordati con il cliente. Leasing o noleggio con opzione di acquisto senza acconto disponibile. Possiamo realizzare altre dimensioni, colori e configurazioni, inclusi WC o attrezzature aggiuntive.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Premium outdoor sauna measuring 4.00 x 2.20 m. Supplied fully assembled and ready to use for private or professional settings, including hotels, spas and wellness centres.\n\nSTANDARD EQUIPMENT\n- HARVIA VEGA 9 kW heater, 400 V power supply, sauna stones included and integrated control unit\n- Stainless-steel interior lining and stone tray\n- Digital controller with 24-hour clock, temperature range 30-115 °C, heating-time limit and digital display\n- Key lock, temperature sensor and 139 °C safety limiter\n- Two sturdy benches with an integrated table, made from Nordic spruce\n\nCONSTRUCTION AND INSULATION\n- Walls and roof made of 7.5 cm insulated sandwich panels\n- Self-supporting welded steel structure\n- Two double-glazed tilt windows\n- Complete electrical installation, interior ceiling lights and 2,000 W wall-mounted electric heater\n\nDelivery and unloading arrangements are agreed with the customer. Leasing or rental with a purchase option and no down payment is available. Other sizes, colours and configurations can be made, including WC or additional equipment.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Sauna extérieure haut de gamme de 4,00 x 2,20 m. Fournie entièrement montée et prête à l’emploi, pour un usage privé ou professionnel, notamment dans les hôtels, spas et centres de bien-être.\n\nÉQUIPEMENTS DE SÉRIE\n- Poêle HARVIA VEGA de 9 kW, alimentation 400 V, pierres incluses et unité de commande intégrée\n- Revêtement intérieur et grille à pierres en acier inoxydable\n- Commande numérique avec horloge 24 heures, température réglable de 30 à 115 °C, limitation du temps de chauffe et affichage numérique\n- Verrouillage des touches, sonde de température et limiteur de sécurité à 139 °C\n- Deux bancs robustes avec table intégrée, en épicéa nordique\n\nCONSTRUCTION ET ISOLATION\n- Murs et toit en panneaux sandwich isolés de 7,5 cm\n- Structure autoportante en acier soudé\n- Deux fenêtres à battant à double vitrage\n- Installation électrique complète, plafonniers intérieurs et radiateur électrique mural de 2 000 W\n\nLes modalités de livraison et de déchargement sont convenues avec le client. Leasing ou location avec option d’achat sans acompte disponible. D’autres dimensions, couleurs et configurations peuvent être réalisées, notamment avec WC ou équipements supplémentaires.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Sauna exterior de alta gama de 4,00 x 2,20 m. Se suministra completamente montada y lista para usar, tanto en entornos privados como profesionales, por ejemplo hoteles, spas y centros de bienestar.\n\nEQUIPAMIENTO DE SERIE\n- Estufa HARVIA VEGA de 9 kW, alimentación de 400 V, piedras incluidas y unidad de control integrada\n- Revestimiento interior y rejilla para piedras de acero inoxidable\n- Control digital con reloj de 24 horas, temperatura regulable de 30 a 115 °C, límite del tiempo de calentamiento y pantalla digital\n- Bloqueo de teclas, sonda de temperatura y limitador de seguridad a 139 °C\n- Dos bancos resistentes con mesa integrada, de abeto rojo nórdico\n\nCONSTRUCCIÓN Y AISLAMIENTO\n- Paredes y techo de paneles sándwich aislados de 7,5 cm\n- Estructura autoportante de acero soldado\n- Dos ventanas abatibles con doble acristalamiento\n- Instalación eléctrica completa, plafones interiores y radiador eléctrico mural de 2.000 W\n\nLa entrega y la descarga se acuerdan con el cliente. Hay leasing o alquiler con opción de compra sin pago inicial. Se pueden fabricar otras dimensiones, colores y configuraciones, incluidos WC o equipamiento adicional.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Hochwertige Aussensauna mit den Massen 4,00 x 2,20 m. Vollständig montiert und einsatzbereit für private oder gewerbliche Nutzung, beispielsweise in Hotels, Spas und Wellnesszentren.\n\nSERIENAUSSTATTUNG\n- HARVIA-VEGA-Ofen mit 9 kW, 400-V-Anschluss, Saunasteine inklusive und integrierter Steuerung\n- Innenverkleidung und Steinkorb aus Edelstahl\n- Digitale Steuerung mit 24-Stunden-Uhr, Temperaturbereich 30-115 °C, Heizzeitbegrenzung und Digitalanzeige\n- Tastensperre, Temperaturfühler und Sicherheitsbegrenzer bei 139 °C\n- Zwei robuste Bänke mit integriertem Tisch aus nordischer Fichte\n\nKONSTRUKTION UND ISOLIERUNG\n- Wände und Dach aus 7,5 cm starken isolierten Sandwichpaneelen\n- Selbsttragende, geschweisste Stahlkonstruktion\n- Zwei Drehfenster mit Doppelverglasung\n- Vollständige Elektroinstallation, Innenleuchten und elektrischer Wandheizkörper mit 2.000 W\n\nLieferung und Entladen werden mit dem Kunden vereinbart. Leasing oder Miete mit Kaufoption ohne Anzahlung ist verfügbar. Andere Masse, Farben und Ausführungen sind möglich, auch mit WC oder zusätzlicher Ausstattung.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Hoogwaardige buitensauna van 4,00 x 2,20 m. Volledig gemonteerd en gebruiksklaar voor privé- of professioneel gebruik, bijvoorbeeld in hotels, spa’s en wellnesscentra.\n\nSTANDAARDUITRUSTING\n- HARVIA VEGA-kachel van 9 kW, 400 V, saunastenen inbegrepen en geïntegreerde bediening\n- Binnenbekleding en stenenrooster van roestvrij staal\n- Digitale bediening met 24-uursklok, temperatuurregeling van 30 tot 115 °C, begrenzing van de verwarmingstijd en digitaal display\n- Toetsvergrendeling, temperatuursensor en veiligheidsbegrenzer op 139 °C\n- Twee stevige banken met geïntegreerde tafel, van nordische spar\n\nCONSTRUCTIE EN ISOLATIE\n- Wanden en dak van geïsoleerde sandwichpanelen van 7,5 cm\n- Zelfdragende gelaste staalconstructie\n- Twee openslaande ramen met dubbele beglazing\n- Volledige elektrische installatie, binnenverlichting en elektrische wandradiator van 2.000 W\n\nLevering en lossen worden met de klant afgesproken. Lease of huur met koopoptie zonder aanbetaling is beschikbaar. Andere afmetingen, kleuren en uitvoeringen zijn mogelijk, inclusief WC of extra uitrusting.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Laadukas ulkosauna, mitat 4,00 x 2,20 m. Toimitetaan täysin koottuna ja käyttövalmiina yksityiseen tai ammattikäyttöön, kuten hotelleihin, kylpylöihin ja hyvinvointikeskuksiin.\n\nVAKIOVARUSTEET\n- HARVIA VEGA 9 kW:n kiuas, 400 V:n syöttö, kiuaskivet ja integroitu ohjausyksikkö\n- Ruostumattomasta teräksestä valmistettu sisäverhous ja kiviritilä\n- Digitaalinen ohjaus, 24 tunnin kello, lämpötila-alue 30-115 °C, lämmitysajan rajoitus ja digitaalinen näyttö\n- Näppäinlukitus, lämpötila-anturi ja 139 °C:n turvarajoitin\n- Kaksi tukevaa pohjoismaisesta kuusesta valmistettua penkkiä integroidulla pöydällä\n\nRAKENNE JA ERISTYS\n- Seinät ja katto 7,5 cm:n eristetyistä sandwich-paneeleista\n- Itsekantava hitsattu teräsrunko\n- Kaksi kaksilasista avattavaa ikkunaa\n- Täydellinen sähköasennus, sisävalaisimet ja 2 000 W:n sähköinen seinälämmitin\n\nToimituksesta ja purkamisesta sovitaan asiakkaan kanssa. Leasing tai vuokraus osto-optiolla ilman käsirahaa on saatavilla. Muita kokoja, värejä ja kokoonpanoja voidaan valmistaa, myös WC:llä tai lisävarusteilla.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Hochwertige Aussensauna mit den Massen 4,00 x 2,20 m. Vollständig montiert und einsatzbereit für private oder gewerbliche Nutzung, beispielsweise in Hotels, Spas und Wellnesszentren.\n\nSERIENAUSSTATTUNG\n- HARVIA-VEGA-Ofen mit 9 kW, 400-V-Anschluss, Saunasteine inklusive und integrierter Steuerung\n- Innenverkleidung und Steinkorb aus Edelstahl\n- Digitale Steuerung mit 24-Stunden-Uhr, Temperaturbereich 30-115 °C, Heizzeitbegrenzung und Digitalanzeige\n- Tastensperre, Temperaturfühler und Sicherheitsbegrenzer bei 139 °C\n- Zwei robuste Bänke mit integriertem Tisch aus nordischer Fichte\n\nKONSTRUKTION UND ISOLIERUNG\n- Wände und Dach aus 7,5 cm starken isolierten Sandwichpaneelen\n- Selbsttragende, geschweisste Stahlkonstruktion\n- Zwei Drehfenster mit Doppelverglasung\n- Vollständige Elektroinstallation, Innenleuchten und elektrischer Wandheizkörper mit 2.000 W\n\nLieferung und Entladen werden mit dem Kunden vereinbart. Leasing oder Miete mit Kaufoption ohne Anzahlung ist verfügbar. Andere Masse, Farben und Ausführungen sind möglich, auch mit WC oder zusätzlicher Ausstattung.')
WHERE `id` = 70 AND `reference` = 'CABINA UFFICIO CONTAINEX BASIC ANTRACITE';

UPDATE `conteneurs`
SET `description` = 'Cabina per posto di guardia.\n\nSTRUTTURA E ISOLAMENTO\n- Pareti e tetto in pannelli sandwich zincati con schiuma PU da 100 mm\n- Rivestimento interno bianco leggermente scanalato\n- Pavimento in PVC su pannelli OSB, facile da mantenere\n\nPORTA E FINESTRE\n- Porta esterna in acciaio zincato Hörmann, 900 x 2.000 mm\n- Tre finestre in PVC: due fisse e una apribile\n\nDOTAZIONI\n- Impianto elettrico completo con lampada, interruttore e prese\n- Radiatore elettrico da 2.000 W disponibile come optional\n- Altri colori disponibili su richiesta\n\nPer lo scarico occorre predisporre attrezzatura adeguata, come un carrello elevatore o una pala gommata. Per clienti professionali sono disponibili leasing o noleggio con opzione di acquisto; è possibile richiedere un’offerta personalizzata.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Guard booth cabin.\n\nSTRUCTURE AND INSULATION\n- Walls and roof made of galvanised sandwich panels with 100 mm PU foam\n- Slightly ribbed white interior wall finish\n- Easy-to-maintain PVC flooring over OSB panels\n\nDOOR AND WINDOWS\n- Hörmann galvanised steel external door, 900 x 2,000 mm\n- Three PVC windows: two fixed and one opening\n\nEQUIPMENT\n- Complete electrical installation with light, switch and sockets\n- Optional 2,000 W electric heater\n- Other colours available on request\n\nSuitable unloading equipment, such as a forklift or wheeled loader, must be provided. Leasing or rental with purchase option is available to business customers; a tailored quotation can be requested.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de poste de garde.\n\nSTRUCTURE ET ISOLATION\n- Murs et toit en panneaux sandwich galvanisés avec mousse PU de 100 mm\n- Revêtement mural intérieur blanc légèrement nervuré\n- Sol en PVC sur panneaux OSB, facile à entretenir\n\nPORTE ET FENÊTRES\n- Porte extérieure en acier galvanisé Hörmann, 900 x 2 000 mm\n- Trois fenêtres en PVC : deux fixes et une ouvrante\n\nÉQUIPEMENTS\n- Installation électrique complète avec lampe, interrupteur et prises\n- Radiateur électrique de 2 000 W disponible en option\n- Autres couleurs disponibles sur demande\n\nUn équipement adapté doit être prévu pour le déchargement, par exemple un chariot élévateur ou une chargeuse sur pneus. Leasing ou location avec option d’achat disponible pour les clients professionnels ; une offre personnalisée peut être demandée.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina para puesto de vigilancia.\n\nESTRUCTURA Y AISLAMIENTO\n- Paredes y techo de paneles sándwich galvanizados con espuma PU de 100 mm\n- Revestimiento interior blanco ligeramente acanalado\n- Suelo de PVC sobre paneles OSB, fácil de mantener\n\nPUERTA Y VENTANAS\n- Puerta exterior de acero galvanizado Hörmann, 900 x 2.000 mm\n- Tres ventanas de PVC: dos fijas y una practicable\n\nEQUIPAMIENTO\n- Instalación eléctrica completa con lámpara, interruptor y enchufes\n- Radiador eléctrico de 2.000 W disponible como opción\n- Otros colores disponibles bajo petición\n\nPara la descarga debe disponerse de equipo adecuado, como una carretilla elevadora o una pala cargadora. Hay leasing o alquiler con opción de compra para clientes profesionales; se puede solicitar un presupuesto personalizado.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Wachkabine.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach aus verzinkten Sandwichpaneelen mit 100 mm PU-Schaum\n- Leicht gerippte, weisse Innenwandverkleidung\n- Pflegeleichter PVC-Boden auf OSB-Platten\n\nTÜR UND FENSTER\n- Äussere verzinkte Stahltür von Hörmann, 900 x 2.000 mm\n- Drei PVC-Fenster: zwei feststehende und ein zu öffnendes Fenster\n\nAUSSTATTUNG\n- Vollständige Elektroinstallation mit Lampe, Schalter und Steckdosen\n- Elektrischer Heizkörper mit 2.000 W optional erhältlich\n- Andere Farben auf Anfrage verfügbar\n\nFür das Entladen ist geeignete Ausrüstung bereitzustellen, beispielsweise ein Gabelstapler oder Radlader. Für Geschäftskunden sind Leasing oder Miete mit Kaufoption verfügbar; eine individuelle Offerte kann angefragt werden.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Wachthuisje.\n\nCONSTRUCTIE EN ISOLATIE\n- Wanden en dak van gegalvaniseerde sandwichpanelen met 100 mm PU-schuim\n- Licht geribbelde witte binnenwandbekleding\n- Gemakkelijk te onderhouden PVC-vloer op OSB-panelen\n\nDEUR EN RAMEN\n- Externe gegalvaniseerde stalen Hörmann-deur, 900 x 2.000 mm\n- Drie PVC-ramen: twee vaste en één te openen raam\n\nUITRUSTING\n- Volledige elektrische installatie met lamp, schakelaar en stopcontacten\n- Elektrische radiator van 2.000 W optioneel beschikbaar\n- Andere kleuren op aanvraag beschikbaar\n\nVoor het lossen moet geschikte apparatuur worden voorzien, zoals een heftruck of wiellader. Voor zakelijke klanten zijn lease of huur met koopoptie beschikbaar; een offerte op maat kan worden aangevraagd.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Vartijankoppi.\n\nRAKENNE JA ERISTYS\n- Seinät ja katto sinkityistä sandwich-paneeleista, joissa on 100 mm PU-vaahtoeristys\n- Sisäseinissä valkoinen, kevyesti uritettu pinnoite\n- Helppohoitoinen PVC-lattia OSB-levyjen päällä\n\nOVI JA IKKUNAT\n- Hörmannin sinkitty teräsovi, 900 x 2 000 mm\n- Kolme PVC-ikkunaa: kaksi kiinteää ja yksi avattava\n\nVARUSTEET\n- Täydellinen sähköasennus, johon kuuluu valaisin, katkaisin ja pistorasiat\n- 2 000 W:n sähköpatteri saatavilla lisävarusteena\n- Muita värejä saatavilla pyynnöstä\n\nPurkamiseen on järjestettävä sopiva kalusto, kuten trukki tai pyöräkuormaaja. Yritysasiakkaille on tarjolla leasing tai vuokraus osto-optiolla; yksilöllisen tarjouksen voi pyytää.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Wachkabine.\n\nSTRUKTUR UND ISOLIERUNG\n- Wände und Dach aus verzinkten Sandwichpaneelen mit 100 mm PU-Schaum\n- Leicht gerippte, weisse Innenwandverkleidung\n- Pflegeleichter PVC-Boden auf OSB-Platten\n\nTÜR UND FENSTER\n- Äussere verzinkte Stahltür von Hörmann, 900 x 2.000 mm\n- Drei PVC-Fenster: zwei feststehende und ein zu öffnendes Fenster\n\nAUSSTATTUNG\n- Vollständige Elektroinstallation mit Lampe, Schalter und Steckdosen\n- Elektrischer Heizkörper mit 2.000 W optional erhältlich\n- Andere Farben auf Anfrage verfügbar\n\nFür das Entladen ist geeignete Ausrüstung bereitzustellen, beispielsweise ein Gabelstapler oder Radlader. Für Geschäftskunden sind Leasing oder Miete mit Kaufoption verfügbar; eine individuelle Offerte kann angefragt werden.')
WHERE `id` = 71 AND `reference` = 'CABINA PER GUARDIA DI PORTA';

UPDATE `conteneurs`
SET `description` = 'Cabina ufficio nuova, dimensioni 4,00 x 2,40 m, altezza 2,70 m. Robusta e isolata, adatta a uso professionale, amministrativo o temporaneo.\n\nCARATTERISTICHE TECNICHE\n- Struttura autoportante in acciaio saldato\n- Peso totale: 1.200 kg\n- Pareti, pavimento e tetto con pannelli sandwich e isolamento termico da 7,5 cm\n- Profili a taglio termico per ridurre la dispersione energetica\n- Due finestre a battente in PVC con doppi vetri\n- Porta esterna Hörmann in acciaio zincato\n- Impianto elettrico completo conforme alle direttive CE, prese da 230 V e plafoniera\n- Pavimento con finitura laminata e radiatore elettrico a parete da 2.000 W\n- Occhielli di sollevamento per gru e guide per carrello elevatore\n\nPer il trasporto e lo scarico occorre predisporre attrezzatura adeguata, come un carrello elevatore o una pala gommata con forche. Possiamo realizzare altre dimensioni e colori secondo le specifiche del cliente. Costi e condizioni di consegna dipendono dalla destinazione e sono indicati nel preventivo.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'New office cabin measuring 4.00 x 2.40 m and 2.70 m high. Robust and insulated, suitable for professional, administrative or temporary use.\n\nTECHNICAL FEATURES\n- Self-supporting welded steel structure\n- Total weight: 1,200 kg\n- Walls, floor and roof with sandwich panels and 7.5 cm thermal insulation\n- Thermally broken profiles to reduce energy loss\n- Two double-glazed PVC tilt windows\n- Hörmann external galvanised steel door\n- Complete CE-compliant electrical installation, 230 V sockets and ceiling light\n- Laminate floor finish and 2,000 W wall-mounted electric heater\n- Crane lifting eyes and forklift guides\n\nSuitable equipment, such as a forklift or wheeled loader with forks, must be arranged for transport and unloading. Other sizes and colours can be made to customer specifications. Delivery costs and terms depend on the destination and are stated in the quotation.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de bureau neuve de 4,00 x 2,40 m et de 2,70 m de hauteur. Robuste et isolée, elle convient à un usage professionnel, administratif ou temporaire.\n\nCARACTÉRISTIQUES TECHNIQUES\n- Structure autoportante en acier soudé\n- Poids total : 1 200 kg\n- Murs, sol et toit en panneaux sandwich avec isolation thermique de 7,5 cm\n- Profils à rupture de pont thermique pour limiter les pertes d’énergie\n- Deux fenêtres PVC à soufflet avec double vitrage\n- Porte extérieure Hörmann en acier galvanisé\n- Installation électrique complète conforme CE, prises 230 V et plafonnier\n- Finition de sol stratifiée et radiateur électrique mural de 2 000 W\n- Anneaux de levage pour grue et guides pour chariot élévateur\n\nUn équipement adapté, tel qu’un chariot élévateur ou une chargeuse sur pneus avec fourches, doit être prévu pour le transport et le déchargement. D’autres dimensions et couleurs peuvent être réalisées selon les spécifications du client. Les frais et modalités de livraison dépendent de la destination et sont indiqués dans le devis.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina de oficina nueva de 4,00 x 2,40 m y 2,70 m de altura. Robusta y aislada, adecuada para uso profesional, administrativo o temporal.\n\nCARACTERÍSTICAS TÉCNICAS\n- Estructura autoportante de acero soldado\n- Peso total: 1.200 kg\n- Paredes, suelo y techo de paneles sándwich con aislamiento térmico de 7,5 cm\n- Perfiles con rotura de puente térmico para reducir la pérdida de energía\n- Dos ventanas abatibles de PVC con doble acristalamiento\n- Puerta exterior Hörmann de acero galvanizado\n- Instalación eléctrica completa conforme a CE, enchufes de 230 V y lámpara de techo\n- Suelo con acabado laminado y radiador eléctrico mural de 2.000 W\n- Argollas para grúa y guías para carretilla elevadora\n\nPara el transporte y la descarga debe disponerse de equipo adecuado, como una carretilla elevadora o una pala cargadora con horquillas. Se pueden fabricar otras dimensiones y colores según las especificaciones del cliente. Los costes y condiciones de entrega dependen del destino y se indican en el presupuesto.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Neue Bürokabine mit den Massen 4,00 x 2,40 m und einer Höhe von 2,70 m. Robust und isoliert, geeignet für berufliche, administrative oder vorübergehende Nutzung.\n\nTECHNISCHE MERKMALE\n- Selbsttragende, geschweisste Stahlkonstruktion\n- Gesamtgewicht: 1.200 kg\n- Wände, Boden und Dach aus Sandwichpaneelen mit 7,5 cm Wärmedämmung\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Zwei PVC-Kippfenster mit Doppelverglasung\n- Äussere Hörmann-Tür aus verzinktem Stahl\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und Deckenleuchte\n- Laminatboden und elektrischer Wandheizkörper mit 2.000 W\n- Kranösen und Staplerführungen\n\nFür Transport und Entladen ist geeignete Ausrüstung bereitzustellen, beispielsweise ein Gabelstapler oder Radlader mit Gabeln. Andere Masse und Farben sind nach Kundenspezifikation möglich. Lieferkosten und -bedingungen hängen vom Bestimmungsort ab und werden im Angebot aufgeführt.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Nieuwe kantoorunit van 4,00 x 2,40 m en 2,70 m hoog. Robuust en geïsoleerd, geschikt voor professioneel, administratief of tijdelijk gebruik.\n\nTECHNISCHE KENMERKEN\n- Zelfdragende gelaste staalconstructie\n- Totaalgewicht: 1.200 kg\n- Wanden, vloer en dak van sandwichpanelen met 7,5 cm thermische isolatie\n- Thermisch onderbroken profielen om energieverlies te beperken\n- Twee PVC-kiepramen met dubbele beglazing\n- Externe Hörmann-deur van gegalvaniseerd staal\n- Volledige CE-conforme elektrische installatie, 230V-stopcontacten en plafondlamp\n- Laminaatvloer en elektrische wandradiator van 2.000 W\n- Hijsogen voor een kraan en heftruckgeleiders\n\nVoor vervoer en lossen moet geschikte apparatuur worden geregeld, zoals een heftruck of wiellader met vorken. Andere afmetingen en kleuren zijn mogelijk volgens de specificaties van de klant. Leveringskosten en -voorwaarden zijn afhankelijk van de bestemming en worden in de offerte vermeld.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Uusi toimistomoduuli, mitat 4,00 x 2,40 m, korkeus 2,70 m. Kestävä ja eristetty ratkaisu ammatilliseen, hallinnolliseen tai tilapäiseen käyttöön.\n\nTEKNISET TIEDOT\n- Itsekantava hitsattu teräsrunko\n- Kokonaispaino: 1 200 kg\n- Seinät, lattia ja katto sandwich-paneeleista, lämpöeristys 7,5 cm\n- Lämpökatkaistut profiilit vähentävät energiahäviötä\n- Kaksi kaksilasista PVC-kippi-ikkunaa\n- Hörmannin ulkoinen sinkitty teräsovi\n- Täydellinen CE-vaatimusten mukainen sähköasennus, 230 V:n pistorasiat ja kattovalaisin\n- Laminaattilattia ja 2 000 W:n sähköinen seinälämmitin\n- Nostokorvakkeet nosturille ja trukkiohjaimet\n\nKuljetusta ja purkua varten on järjestettävä sopiva kalusto, kuten trukki tai haarukoilla varustettu pyöräkuormaaja. Muita mittoja ja värejä voidaan valmistaa asiakkaan vaatimusten mukaan. Toimituskulut ja -ehdot riippuvat kohteesta ja ilmoitetaan tarjouksessa.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Neue Bürokabine mit den Massen 4,00 x 2,40 m und einer Höhe von 2,70 m. Robust und isoliert, geeignet für berufliche, administrative oder vorübergehende Nutzung.\n\nTECHNISCHE MERKMALE\n- Selbsttragende, geschweisste Stahlkonstruktion\n- Gesamtgewicht: 1.200 kg\n- Wände, Boden und Dach aus Sandwichpaneelen mit 7,5 cm Wärmedämmung\n- Thermisch getrennte Profile zur Verringerung des Energieverlusts\n- Zwei PVC-Kippfenster mit Doppelverglasung\n- Äussere Hörmann-Tür aus verzinktem Stahl\n- CE-konforme Elektroinstallation, 230-V-Steckdosen und Deckenleuchte\n- Laminatboden und elektrischer Wandheizkörper mit 2.000 W\n- Kranösen und Staplerführungen\n\nFür Transport und Entladen ist geeignete Ausrüstung bereitzustellen, beispielsweise ein Gabelstapler oder Radlader mit Gabeln. Andere Masse und Farben sind nach Kundenspezifikation möglich. Lieferkosten und -bedingungen hängen vom Bestimmungsort ab und werden im Angebot aufgeführt.')
WHERE `id` = 73 AND `reference` = 'CABINA DA UFFICIO PROTEZIONE DI GUARDIA SICUREZZA';

UPDATE `conteneurs`
SET `description` = 'Cabina ufficio con zona soggiorno e WC integrato, dimensioni 4,00 x 2,00 m. Soluzione modulare pronta all’uso, adatta a uffici, cantieri e spazi amministrativi.\n\nDIMENSIONI\n- Lunghezza: 4,00 m; larghezza: 2,00 m\n- Altezza esterna: 2,62 m; altezza con occhielli: 2,70 m\n\nSTRUTTURA E ISOLAMENTO\n- Struttura in acciaio 100 x 50 x 4 mm\n- Pareti in pannelli sandwich isolati da 75 mm\n- Pavimento in pannelli OSB su telaio in acciaio 100 x 100 mm\n\nPORTE, FINESTRE E DOTAZIONI\n- Una finestra oscillante in PVC e una finestra ribaltabile in PVC; tapparelle opzionali\n- Porta d’ingresso Hörmann\n- Impianto elettrico completo con prese, quadro elettrico e illuminazione fluorescente\n- Radiatore elettrico a parete\n- Pavimento con finitura laminata resistente e facile da mantenere\n- WC integrato\n- Quattro occhielli sul tetto per sollevamento con gru e passaggi per carrelli elevatori nella parte inferiore\n\nPossiamo realizzare altre dimensioni e colori secondo le specifiche del cliente. I tempi indicativi di produzione sono circa quattro settimane se il prodotto non è disponibile a magazzino. Le modalità e i costi di consegna sono concordati nel preventivo; il cliente deve predisporre lo scarico.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Office cabin with a living area and integrated WC, measuring 4.00 x 2.00 m. A ready-to-use modular solution for offices, construction sites and administrative spaces.\n\nDIMENSIONS\n- Length: 4.00 m; width: 2.00 m\n- External height: 2.62 m; height including lifting eyes: 2.70 m\n\nSTRUCTURE AND INSULATION\n- Steel structure: 100 x 50 x 4 mm\n- Walls made of 75 mm insulated sandwich panels\n- OSB floor panels on a 100 x 100 mm steel frame\n\nDOORS, WINDOWS AND EQUIPMENT\n- One PVC pivot window and one PVC tilt window; roller shutters optional\n- Hörmann entrance door\n- Complete electrical installation with sockets, electrical panel and fluorescent lighting\n- Wall-mounted electric heater\n- Durable, easy-to-maintain laminate floor finish\n- Integrated WC\n- Four roof lifting eyes for crane handling and lower forklift passages\n\nOther sizes and colours can be made to customer specifications. Indicative production time is about four weeks if the product is not in stock. Delivery terms and costs are agreed in the quotation; the customer must arrange unloading.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de bureau avec espace séjour et WC intégré, dimensions 4,00 x 2,00 m. Solution modulaire prête à l’emploi, adaptée aux bureaux, chantiers et espaces administratifs.\n\nDIMENSIONS\n- Longueur : 4,00 m ; largeur : 2,00 m\n- Hauteur extérieure : 2,62 m ; hauteur avec anneaux de levage : 2,70 m\n\nSTRUCTURE ET ISOLATION\n- Structure en acier de 100 x 50 x 4 mm\n- Murs en panneaux sandwich isolés de 75 mm\n- Plancher en panneaux OSB sur cadre en acier de 100 x 100 mm\n\nPORTES, FENÊTRES ET ÉQUIPEMENTS\n- Une fenêtre PVC pivotante et une fenêtre PVC basculante ; volets roulants en option\n- Porte d’entrée Hörmann\n- Installation électrique complète avec prises, tableau électrique et éclairage fluorescent\n- Radiateur électrique mural\n- Finition de sol stratifiée résistante et facile à entretenir\n- WC intégré\n- Quatre anneaux sur le toit pour le levage par grue et passages inférieurs pour chariot élévateur\n\nD’autres dimensions et couleurs peuvent être réalisées selon les spécifications du client. Le délai de fabrication indicatif est d’environ quatre semaines si le produit n’est pas en stock. Les modalités et frais de livraison sont convenus dans le devis ; le client doit prévoir le déchargement.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina de oficina con zona de estar y WC integrado, de 4,00 x 2,00 m. Solución modular lista para usar, adecuada para oficinas, obras y espacios administrativos.\n\nDIMENSIONES\n- Longitud: 4,00 m; anchura: 2,00 m\n- Altura exterior: 2,62 m; altura con argollas: 2,70 m\n\nESTRUCTURA Y AISLAMIENTO\n- Estructura de acero de 100 x 50 x 4 mm\n- Paredes de paneles sándwich aislados de 75 mm\n- Suelo de paneles OSB sobre bastidor de acero de 100 x 100 mm\n\nPUERTAS, VENTANAS Y EQUIPAMIENTO\n- Una ventana pivotante de PVC y una ventana abatible de PVC; persianas opcionales\n- Puerta de entrada Hörmann\n- Instalación eléctrica completa con enchufes, cuadro eléctrico e iluminación fluorescente\n- Radiador eléctrico mural\n- Suelo con acabado laminado resistente y fácil de mantener\n- WC integrado\n- Cuatro argollas en el techo para elevación con grúa y pasos inferiores para carretilla elevadora\n\nSe pueden fabricar otras dimensiones y colores según las especificaciones del cliente. El plazo de fabricación orientativo es de unas cuatro semanas si el producto no está en stock. Las condiciones y los costes de entrega se acuerdan en el presupuesto; el cliente debe organizar la descarga.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Bürokabine mit Wohnbereich und integriertem WC, Masse 4,00 x 2,00 m. Eine einsatzbereite modulare Lösung für Büros, Baustellen und Verwaltungsbereiche.\n\nMASSE\n- Länge: 4,00 m; Breite: 2,00 m\n- Aussenhöhe: 2,62 m; Höhe mit Hebeösen: 2,70 m\n\nSTRUKTUR UND ISOLIERUNG\n- Stahlkonstruktion: 100 x 50 x 4 mm\n- Wände aus 75 mm starken isolierten Sandwichpaneelen\n- OSB-Bodenplatten auf einem 100 x 100 mm starken Stahlrahmen\n\nTÜREN, FENSTER UND AUSSTATTUNG\n- Ein schwenkbares PVC-Fenster und ein kippbares PVC-Fenster; Rollläden optional\n- Eingangstür von Hörmann\n- Vollständige Elektroinstallation mit Steckdosen, Elektrokasten und Leuchtstoffbeleuchtung\n- Elektrischer Wandheizkörper\n- Strapazierfähige, pflegeleichte Laminatbodenoberfläche\n- Integriertes WC\n- Vier Dachösen für das Anheben mit einem Kran und untere Staplerdurchführungen\n\nAndere Masse und Farben sind nach Kundenspezifikation möglich. Die voraussichtliche Produktionszeit beträgt etwa vier Wochen, falls das Produkt nicht ab Lager verfügbar ist. Lieferbedingungen und -kosten werden im Angebot vereinbart; der Kunde muss das Entladen organisieren.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Kantoorunit met zitruimte en geïntegreerd toilet, 4,00 x 2,00 m. Een gebruiksklare modulaire oplossing voor kantoren, bouwplaatsen en administratieve ruimtes.\n\nAFMETINGEN\n- Lengte: 4,00 m; breedte: 2,00 m\n- Buitenhoogte: 2,62 m; hoogte inclusief hijsogen: 2,70 m\n\nCONSTRUCTIE EN ISOLATIE\n- Stalen constructie van 100 x 50 x 4 mm\n- Wanden van geïsoleerde sandwichpanelen van 75 mm\n- OSB-vloerpanelen op een stalen frame van 100 x 100 mm\n\nDEUREN, RAMEN EN UITRUSTING\n- Eén draaibaar PVC-raam en één kiepraam van PVC; rolluiken optioneel\n- Hörmann-toegangsdeur\n- Volledige elektrische installatie met stopcontacten, elektriciteitskast en tl-verlichting\n- Elektrische wandradiator\n- Sterke, gemakkelijk te onderhouden laminaatvloer\n- Geïntegreerd toilet\n- Vier hijsogen op het dak voor een kraan en onderste heftruckdoorgangen\n\nAndere afmetingen en kleuren zijn mogelijk volgens de specificaties van de klant. De indicatieve productietijd is ongeveer vier weken als het product niet op voorraad is. De leveringsvoorwaarden en -kosten worden in de offerte afgesproken; de klant moet het lossen regelen.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Toimistomoduuli, jossa on oleskelutila ja integroitu WC, mitat 4,00 x 2,00 m. Käyttövalmis moduuliratkaisu toimistoihin, työmaille ja hallintotiloihin.\n\nMITAT\n- Pituus: 4,00 m; leveys: 2,00 m\n- Ulkokorkeus: 2,62 m; korkeus nostokorvakkeineen: 2,70 m\n\nRAKENNE JA ERISTYS\n- Teräsrunko: 100 x 50 x 4 mm\n- Seinät 75 mm:n eristetyistä sandwich-paneeleista\n- OSB-lattialevyt 100 x 100 mm:n teräsrungon päällä\n\nOVET, IKKUNAT JA VARUSTEET\n- Yksi kääntyvä PVC-ikkuna ja yksi kallistettava PVC-ikkuna; rullaverhot lisävarusteena\n- Hörmann-sisäänkäyntiovi\n- Täydellinen sähköasennus, pistorasiat, sähkökeskus ja loistevalaistus\n- Sähköinen seinälämmitin\n- Kestävä ja helppohoitoinen laminaattilattia\n- Integroitu WC\n- Neljä kattonostokorvaketta ja alaosan trukkiaukot\n\nMuita mittoja ja värejä voidaan valmistaa asiakkaan vaatimusten mukaan. Arvioitu valmistusaika on noin neljä viikkoa, jos tuotetta ei ole varastossa. Toimitusehdot ja -kulut sovitaan tarjouksessa; asiakkaan on järjestettävä purku.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Bürokabine mit Wohnbereich und integriertem WC, Masse 4,00 x 2,00 m. Eine einsatzbereite modulare Lösung für Büros, Baustellen und Verwaltungsbereiche.\n\nMASSE\n- Länge: 4,00 m; Breite: 2,00 m\n- Aussenhöhe: 2,62 m; Höhe mit Hebeösen: 2,70 m\n\nSTRUKTUR UND ISOLIERUNG\n- Stahlkonstruktion: 100 x 50 x 4 mm\n- Wände aus 75 mm starken isolierten Sandwichpaneelen\n- OSB-Bodenplatten auf einem 100 x 100 mm starken Stahlrahmen\n\nTÜREN, FENSTER UND AUSSTATTUNG\n- Ein schwenkbares PVC-Fenster und ein kippbares PVC-Fenster; Rollläden optional\n- Eingangstür von Hörmann\n- Vollständige Elektroinstallation mit Steckdosen, Elektrokasten und Leuchtstoffbeleuchtung\n- Elektrischer Wandheizkörper\n- Strapazierfähige, pflegeleichte Laminatbodenoberfläche\n- Integriertes WC\n- Vier Dachösen für das Anheben mit einem Kran und untere Staplerdurchführungen\n\nAndere Masse und Farben sind nach Kundenspezifikation möglich. Die voraussichtliche Produktionszeit beträgt etwa vier Wochen, falls das Produkt nicht ab Lager verfügbar ist. Lieferbedingungen und -kosten werden im Angebot vereinbart; der Kunde muss das Entladen organisieren.')
WHERE `id` = 74 AND `reference` = 'CABINA UFFICIO / SALOTTO CON WC';

COMMIT;
